ALGORITHM ExactGenerationProbability(n)
  INPUT : positive integer n
  OUTPUT: P(S_n), the probability two random permutations generate S_n

  target  <- n!                         // size of the full symmetric group
  E       <- all n! permutations of {0..n-1}   (one-line tuples)
  g       <- 0                          // running count of generating pairs

  for each a in E:
      for each b in E:
          C <- GeneratedSubgroup({a, b}, n)
          if |C| = target then
              g <- g + 1

  return g / (n!)^2

SUBROUTINE GeneratedSubgroup(S, n)
  e        <- identity permutation on {0..n-1}
  closure  <- { e }
  gens     <- S union { inverse(s) : s in S }
  frontier <- [ e ]
  while frontier is non-empty:
      next <- [ ]
      for x in frontier:
          for h in gens:
              y <- compose(h, x)
              if y not in closure:
                  add y to closure
                  append y to next
      frontier <- next
  return closure

