from __future__ import annotations
from itertools import permutations
from math import factorial
from typing import List, Tuple

Perm = Tuple[int, ...]

def compose(p: Perm, q: Perm) -> Perm:
    """Compose permutations: (p . q)(i) = p(q(i))."""
    return tuple(p[q[i]] for i in range(len(p)))

def inverse(p: Perm) -> Perm:
    """Inverse permutation."""
    inv = [0] * len(p)
    for i, pi in enumerate(p):
        inv[pi] = i
    return tuple(inv)

def generated_subgroup(generators: List[Perm], n: int) -> "frozenset[Perm]":
    """Breadth-first orbit closure of the subgroup generated by `generators`."""
    e: Perm = tuple(range(n))
    closure = {e}
    gens = list(generators) + [inverse(g) for g in generators]
    frontier = [e]
    while frontier:
        nxt: List[Perm] = []
        for x in frontier:
            for g in gens:
                y = compose(g, x)
                if y not in closure:
                    closure.add(y)
                    nxt.append(y)
        frontier = nxt
    return frozenset(closure)

def count_generating_pairs(n: int) -> int:
    """Exact number of ordered pairs (a, b) that generate S_n."""
    target = factorial(n)
    elts = list(permutations(range(n)))
    return sum(
        1
        for a in elts
        for b in elts
        if len(generated_subgroup([a, b], n)) == target
    )

def generation_probability(n: int) -> float:
    """Exact generation probability P(S_n) = g / (n!)^2 as a float."""
    return count_generating_pairs(n) / (factorial(n) ** 2)
